import {render, screen} from '@testing-library/react';
import {describe, expect, it} from 'vitest';
import {Markdown} from './markdown';

const show = (source: string) => render(<Markdown source={source} />);

describe('Markdown', () => {
  it('renders the blocks the START HERE report uses', () => {
    const {container} = show(
      [
        '# START HERE – Example project',
        '',
        '> Generated by Mission Control.',
        '',
        '## Status',
        '',
        '- **Sprint:** 0 of 2 done',
        '- Blocked: 1',
        '',
        'A paragraph',
        'over two lines.',
      ].join('\n')
    );

    // The page already has an h1, so report headings move one level down.
    expect(
      screen.getByRole('heading', {
        level: 2,
        name: 'START HERE – Example project',
      })
    ).toBeVisible();
    expect(
      screen.getByRole('heading', {level: 3, name: 'Status'})
    ).toBeVisible();
    expect(container.querySelector('blockquote')).toHaveTextContent(
      'Generated by Mission Control.'
    );
    expect(screen.getAllByRole('listitem').map(li => li.textContent)).toEqual([
      'Sprint: 0 of 2 done',
      'Blocked: 1',
    ]);
    expect(screen.getByText('Sprint:').tagName).toBe('STRONG');
    expect(screen.getByText('A paragraph over two lines.').tagName).toBe('P');
  });

  it('renders bold, italic, code and links inside a line', () => {
    show(
      '_Generated._ Use `click_id` and see [B-12](https://github.com/o/r/blob/develop/data/decisions.yaml#L1) **now**.'
    );

    expect(screen.getByText('Generated.').tagName).toBe('EM');
    expect(screen.getByText('click_id').tagName).toBe('CODE');
    expect(screen.getByRole('link', {name: 'B-12'})).toHaveAttribute(
      'href',
      'https://github.com/o/r/blob/develop/data/decisions.yaml#L1'
    );
    expect(screen.getByText('now').tagName).toBe('STRONG');
  });

  it('keeps underscores inside words as text', () => {
    show('Branch feature/<issue>-short_name from develop.');

    expect(
      screen.getByText('Branch feature/<issue>-short_name from develop.')
    ).toBeVisible();
    expect(document.querySelector('em')).toBeNull();
  });

  it('never renders raw HTML or non-web links', () => {
    const {container} = show(
      '<img src=x onerror="alert(1)"> and [click](javascript:alert(1))'
    );

    expect(container.querySelector('img')).toBeNull();
    expect(screen.queryByRole('link')).not.toBeInTheDocument();
    expect(container).toHaveTextContent(
      '<img src=x onerror="alert(1)"> and click'
    );
  });
});
